#!/usr/bin/env sh
# Pins the rules of the semgrep registry packs below to the newest commit of
# semgrep/semgrep-rules. The rules are fetched in CI and never committed: their
# license does not allow redistribution.
set -eu
cd "$(dirname "$0")"
packs="typescript javascript nodejs dockerfile github-actions owasp-top-ten"
commit=$(git ls-remote https://github.com/semgrep/semgrep-rules HEAD | cut -f1)
rules=
for pack in $packs; do
  config=$(curl -fsSL "https://semgrep.dev/c/p/$pack")
  rules="$rules$(printf '%s\n' "$config" | sed -n 's/^- id: *//p')
"
done
{
  echo "# Generated by update-rules.sh from the semgrep registry packs (p/<name>): $packs."
  echo "repository https://github.com/semgrep/semgrep-rules"
  echo "commit $commit"
  printf '%s' "$rules" | sort -u | sed '/^$/d; s/^/rule /'
} > rules.lock.tmp
mv rules.lock.tmp rules.lock
echo "Pinned $(grep -c '^rule ' rules.lock) rules at $commit"
